import { createHash } from 'node:crypto';

const sha256Norm = (val?: string | null): string | undefined => {
  if (!val) return undefined;
  const cleaned = val.trim().toLowerCase();
  return cleaned ? createHash('sha256').update(cleaned).digest('hex') : undefined;
};

// Meta CAPI yêu cầu số điện thoại chỉ chứa chữ số mã quốc gia + số thuê bao (vd: 84901234567)
const normalizePhoneForMetaHash = (phoneE164?: string | null): string | undefined => {
  if (!phoneE164) return undefined;
  const digitsOnly = phoneE164.replace(/\D/g, '');
  if (digitsOnly.startsWith('0')) return `84${digitsOnly.slice(1)}`;
  return digitsOnly;
};

export interface StitchedCustomerContext {
  masterCustomerId: string;
  phoneE164: string;
  email?: string;
  fbp?: string;
  fbc?: string;
  clientIp?: string;
  userAgent?: string;
}

export async function dispatchMetaCapiQualifiedEvent(
  pixelId: string,
  accessToken: string,
  customer: StitchedCustomerContext,
  eventId: string,
  eventName: 'QualifiedLead' | 'DisqualifiedLead' | 'Purchase',
  valueVnd = 0
) {
  const phoneDigits = normalizePhoneForMetaHash(customer.phoneE164);
  const payload = {
    data: [
      {
        event_name: eventName,
        event_time: Math.floor(Date.now() / 1000),
        event_id: eventId, // Trùng khớp với event_id phía Browser nếu có để chống đếm lặp
        action_source: 'system_generated',
        user_data: {
          ph: phoneDigits ? [sha256Norm(phoneDigits)] : undefined,
          em: customer.email ? [sha256Norm(customer.email)] : undefined,
          external_id: [sha256Norm(customer.masterCustomerId)],
          country: [sha256Norm('vn')],
          fbp: customer.fbp || undefined, // KHÔNG băm fbp / fbc / IP / User-Agent
          fbc: customer.fbc || undefined,
          client_ip_address: customer.clientIp || undefined,
          client_user_agent: customer.userAgent || undefined,
        },
        custom_data: {
          currency: 'VND',
          value: valueVnd,
          lead_pipeline_stage: eventName,
        },
      },
    ],
  };

  const res = await fetch(`https://graph.facebook.com/v21.0/${pixelId}/events?access_token=${accessToken}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(`Meta CAPI error ${res.status}: ${await res.text()}`);
  return res.json();
}
